spec.expr:
sum (
  rate(camunda_authentication_external_requests_seconds_count{domain="identity", namespace=~"$namespace", service=~"$service", pod=~"$pod"}[$__rate_interval])
) by (namespace, service, status, uri)

sum by(method, statusCode) (
  rate(grpc_server_processing_duration_seconds_count{
    statusCode=~"UNAUTHENTICATED|PERMISSION_DENIED",
    namespace=~"$namespace",
    service=~"$service",
    pod=~"$pod"
  }[$__rate_interval]) != 0
)

sum (
  increase(camunda_authentication_external_requests_seconds_count{
    domain="identity",
    namespace=~"$namespace",
    service=~"$service",
    pod=~"$pod"
  }[$__rate_interval])
) by (namespace, status, uri)

sum by (uri,status)(
  rate(http_server_requests_seconds_count{
    outcome="CLIENT_ERROR",
    status=~"401|403",
    namespace=~"$namespace",
    service=~"$service",
    pod=~"$pod"
  }[$__rate_interval])
)

sum by(method, statusCode) (
  rate(grpc_server_processing_duration_seconds_count{
    statusCode=~"UNAUTHENTICATED|PERMISSION_DENIED",
    namespace=~"$namespace",
    service=~"$service",
    pod=~"$pod"
  }[$__rate_interval]) != 0
)

sum by (uri,status)(
  rate(http_server_requests_seconds_count{
    outcome="CLIENT_ERROR",
    status=~"401|403",
    namespace=~"$namespace",
    service=~"$service",
    pod=~"$pod"
  }[$__rate_interval])
)
